  width = 8,
  height = 10,
  units = "in",
  dpi = 300
)

component_plot <- observed_scaled_annual_budget %>%
  dplyr::select(
    SITE_ID, Year,
    observed_total_scaled_annual_gC_m2_yr = observed_scaled_annual_gC_m2_yr,
    observed_FG_scaled_annual_gC_m2_yr,
    observed_storage_scaled_annual_gC_m2_yr
  ) %>%
  pivot_longer(
    cols = -c(SITE_ID, Year),
    names_to = "component",
    values_to = "annual_budget_gC_m2_yr"
  ) %>%
  mutate(
    component = recode(
      component,
      observed_total_scaled_annual_gC_m2_yr = "Total observed scaled",
      observed_FG_scaled_annual_gC_m2_yr = "Gradient flux component",
      observed_storage_scaled_annual_gC_m2_yr = "Storage component"
    )
  ) %>%
  ggplot(aes(x = component, y = annual_budget_gC_m2_yr, color = component)) +
  geom_hline(yintercept = 0, linetype = "dashed", color = "grey45") +
  geom_boxplot(outlier.shape = NA, alpha = 0.12, width = 0.55) +
  geom_jitter(width = 0.15, alpha = 0.55, size = 1.4) +
  theme_bw(base_size = 10.5) +
  labs(
    x = NULL,
    y = expression("Observed scaled annual CH"[4] * " budget (g C m"^-2 * " yr"^-1 * ")"),
    color = NULL,
    title = "Observed-only scaled annual budgets by total-flux component"
  ) +
  theme(
    plot.title = element_text(face = "bold"),
    legend.position = "none",
    axis.text.x = element_text(angle = 20, hjust = 1)
  )

